// Pure JS SHA-256 and HMAC-SHA256 (No require('crypto') needed)
function sha256Bytes(bytes) {
  function rightRotate(value, amount) {
    return (value >>> amount) | (value << (32 - amount));
  }
  const mathPow = Math.pow;
  const maxWord = mathPow(2, 32);
  let i, j;
  const words = [];
  const byteLen = bytes.length;
  const bitLen = byteLen * 8;
  let hash = [];
  const k = [];
  let primeCounter = 0;
  const isComposite = {};
  for (let candidate = 2; primeCounter < 64; candidate++) {
    if (!isComposite[candidate]) {
      for (i = 0; i < 313; i += candidate) isComposite[i] = candidate;
      hash[primeCounter] = (mathPow(candidate, 0.5) * maxWord) | 0;
      k[primeCounter++] = (mathPow(candidate, 1 / 3) * maxWord) | 0;
    }
  }
  hash = hash.slice(0, 8);
  const padded = new Uint8Array(((byteLen + 9 + 63) >> 6) << 6);
  padded.set(bytes);
  padded[byteLen] = 0x80;
  const view = new DataView(padded.buffer);
  view.setUint32(padded.length - 4, bitLen, false);
  view.setUint32(padded.length - 8, Math.floor(bitLen / maxWord), false);

  for (i = 0; i < padded.length; i += 4) {
    words.push(view.getUint32(i, false));
  }

  for (j = 0; j < words.length; ) {
    const w = words.slice(j, (j += 16));
    const oldHash = hash;
    hash = hash.slice(0, 8);
    for (i = 0; i < 64; i++) {
      const w15 = w[i - 15], w2 = w[i - 2];
      const s0 = rightRotate(w15, 7) ^ rightRotate(w15, 18) ^ (w15 >>> 3);
      const s1 = rightRotate(w2, 17) ^ rightRotate(w2, 19) ^ (w2 >>> 10);
      w[i] = i < 16 ? w[i] : (w[i - 16] + s0 + w[i - 7] + s1) | 0;
      const ch = (hash[4] & hash[5]) ^ (~hash[4] & hash[6]);
      const maj = (hash[0] & hash[1]) ^ (hash[0] & hash[2]) ^ (hash[1] & hash[2]);
      const s0_2 = rightRotate(hash[0], 2) ^ rightRotate(hash[0], 13) ^ rightRotate(hash[0], 22);
      const s1_2 = rightRotate(hash[4], 6) ^ rightRotate(hash[4], 11) ^ rightRotate(hash[4], 25);
      const temp1 = hash[7] + s1_2 + ch + k[i] + w[i];
      const temp2 = s0_2 + maj;
      hash = [(temp1 + temp2) | 0].concat(hash);
      hash[4] = (hash[4] + temp1) | 0;
      hash.length = 8;
    }
    for (i = 0; i < 8; i++) hash[i] = (hash[i] + oldHash[i]) | 0;
  }
  const out = new Uint8Array(32);
  const outView = new DataView(out.buffer);
  for (i = 0; i < 8; i++) outView.setUint32(i * 4, hash[i], false);
  return out;
}

function hmacSha256(keyStr, msgStr) {
  const enc = new TextEncoder();
  let key = enc.encode(keyStr);
  const msg = enc.encode(msgStr);
  const b = 64;
  if (key.length > b) key = sha256Bytes(key);
  const kPad = new Uint8Array(b);
  kPad.set(key);
  const iPad = new Uint8Array(b + msg.length);
  const oPad = new Uint8Array(b + 32);
  for (let i = 0; i < b; i++) {
    iPad[i] = kPad[i] ^ 0x36;
    oPad[i] = kPad[i] ^ 0x5c;
  }
  iPad.set(msg, b);
  const innerHash = sha256Bytes(iPad);
  oPad.set(innerHash, b);
  const outerHash = sha256Bytes(oPad);
  return Array.from(outerHash).map(x => x.toString(16).padStart(2, '0')).join('');
}

function sha256Hex(str) {
  const enc = new TextEncoder();
  const hash = sha256Bytes(enc.encode(str));
  return Array.from(hash).map(x => x.toString(16).padStart(2, '0')).join('');
}

// 1. Verify Timestamp & HMAC Signature
const headers = $input.item.json.headers;
const body = $input.item.json.body;
const rawBody = $input.item.json.rawBody || JSON.stringify(body);

const timestamp = parseInt(headers['x-portfolio-timestamp'] || '0', 10);
const providedSignature = (headers['x-portfolio-signature'] || '').toLowerCase();
const correlationId = headers['x-correlation-id'] || 'no-correlation-id';

const hmacSecret = 'ea65e1d3f735f05969844f2b85d8fbbe7157f27ba24487dc10f0e6b0c79e17c3';

const nowSeconds = Math.floor(Date.now() / 1000);
if (Math.abs(nowSeconds - timestamp) > 300) {
  return [{ json: { ok: false, code: 'TIMESTAMP_DRIFT_EXCEEDED', correlationId, isSpam: false, status: 401 } }];
}

const expectedPayload = timestamp + '.' + rawBody;
const expectedSignature = hmacSha256(hmacSecret, expectedPayload).toLowerCase();

if (providedSignature !== expectedSignature) {
  return [{ json: { ok: false, code: 'INQUIRY_INVALID_SIGNATURE', correlationId, isSpam: false, status: 401 } }];
}

// 2. Honeypot check
if (body.website && body.website.trim().length > 0) {
  return [{ json: { ok: true, leadId: 'LEAD-HONEYPOT', correlationId, isSpam: true, status: 200 } }];
}

// 3. Generate 24h Dedupe Key & Lead ID
const emailNormalized = (body.email || '').trim().toLowerCase();
const today = new Date().toISOString().slice(0, 10);
const dedupeKey = sha256Hex(emailNormalized + '_' + body.serviceKey + '_' + today);

const dateFormatted = today.replace(/-/g, '');
const randomSuffix = Math.random().toString(36).substring(2, 8).toUpperCase();
const leadId = 'LEAD-' + dateFormatted + '-' + randomSuffix;

return [{
  json: {
    ok: true,
    leadId,
    dedupeKey,
    correlationId,
    isSpam: false,
    lead_id: leadId,
    created_at: new Date().toISOString(),
    full_name: body.fullName,
    email: emailNormalized,
    organization: body.organization || '',
    phone: body.phone || '',
    service_key: body.serviceKey,
    requirement: body.requirement,
    timeline: body.timeline || '1_3_MONTHS',
    budget_range: body.budgetRange || 'NOT_SURE',
    preferred_channel: body.preferredChannel || 'EMAIL',
    source_path: body.sourcePath || '/contact',
    source_project_id: body.sourceProjectId || '',
    consent: true,
    status: 'NEW',
    owner_notification_status: 'PENDING',
    client_ack_status: 'PENDING',
    dedupe_key: dedupeKey,
    correlation_id: correlationId
  }
}];

